/* Read a length-prefixed message off the socket into a fixed buffer. */
char buf[1024];
int len = read_int(sock);            /* length taken from the network */
if (len > (int)sizeof(buf)) {
    return -1;                       /* too big: reject */
}
memcpy(buf, payload, len);           /* len is converted to size_t here */

